commands.command:
ROOT_PW=$(cat /root/.root_pw); mysql -u root -p"${ROOT_PW}" <<SQL
GRANT RELOAD, LOCK TABLES, PROCESS, REPLICATION CLIENT ON *.* TO 'sstuser'@'localhost';
FLUSH PRIVILEGES;
SQL
echo EXIT:$?

commands.stdout:
******************** IMPORTANT ***********************
To make this policy package active, execute:

semodule -i mariabackup_sst.pp

---

module mariabackup_sst 1.0;

require {
	type mysqld_t;
	class unix_stream_socket connectto;
}

#============= mysqld_t ==============

#!!!! This avc can be allowed using the boolean 'daemons_enable_cluster_mode'
allow mysqld_t self:unix_stream_socket connectto;

commands.command:
ROOT_PW=$(cat /root/.root_pw); mysql -u root -p"${ROOT_PW}" <<'SQL'
CREATE DATABASE IF NOT EXISTS appdb;
USE appdb;
CREATE TABLE IF NOT EXISTS orders (id INT AUTO_INCREMENT PRIMARY KEY, item VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO orders (item) VALUES ('widget-a'), ('widget-b'), ('widget-c');
SELECT COUNT(*) FROM orders;
SQL
